"use client"

import * as React from "react"
import * as NavigationMenuPrimitive from "@radix-ui/react-navigation-menu"

import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"

type Variant = "names" | "lead" | "inline"
const VariantContext = React.createContext<Variant>("names")

type NavigationMenuProps = React.ComponentProps<typeof NavigationMenuPrimitive.Root> & {
  /**
   * names: a panel of large names hung under the menu.
   * lead: a contents page; the names small in a column, and the one you point at or focus set as the headline beside them, with its line.
   * inline: one line of thought; pressing a word opens its names into the line after it, and the words after make room.
   */
  variant?: Variant
}

/**
 * Small words that open a panel of large names. Radix keeps the pointer delay,
 * focus and arrow keys; each panel spans the width of the menu, hung under it.
 * There is no viewport: every panel sits in its own item.
 */
function NavigationMenu({ variant = "names", className, dir, ref, ...props }: NavigationMenuProps) {
  // Radix writes dir="ltr" on the nav unless told otherwise. Without a dir, the menu takes the direction
  // of the page around it, read as it mounts (as the menus and the tabs do), so its words and keys mirror.
  const [around, setAround] = React.useState<"rtl">()
  const composedRef = useComposedRefs(React.useCallback((node: HTMLElement | null) => {
    const up = node?.parentElement
    if (!dir && up && getComputedStyle(up).direction === "rtl") setAround("rtl")
  }, [dir]), ref)
  return (
    <VariantContext.Provider value={variant}>
      <NavigationMenuPrimitive.Root
        ref={composedRef}
        dir={dir ?? around}
        data-slot="navigation-menu"
        data-variant={variant}
        className={cn("db-navmenu", className)}
        {...props}
      />
    </VariantContext.Provider>
  )
}

function NavigationMenuList({ className, ...props }: React.ComponentProps<typeof NavigationMenuPrimitive.List>) {
  return <NavigationMenuPrimitive.List data-slot="navigation-menu-list" className={className} {...props} />
}

function NavigationMenuItem(props: React.ComponentProps<typeof NavigationMenuPrimitive.Item>) {
  return <NavigationMenuPrimitive.Item data-slot="navigation-menu-item" {...props} />
}

/** Inline, the names open into the line, so a passing pointer must not open them: only a press does. */
const held = (e: React.PointerEvent) => e.preventDefault()

/** A small word with a ↓ that turns over while its panel is open (inline: a → that inks). */
function NavigationMenuTrigger({ className, onPointerMove, onPointerLeave, ...props }: React.ComponentProps<typeof NavigationMenuPrimitive.Trigger>) {
  const inline = React.useContext(VariantContext) === "inline"
  return (
    <NavigationMenuPrimitive.Trigger
      data-slot="navigation-menu-trigger"
      className={className}
      onPointerMove={(e) => (onPointerMove?.(e), inline && held(e))}
      onPointerLeave={(e) => (onPointerLeave?.(e), inline && held(e))}
      {...props}
    />
  )
}

/** The panel. Its children are NavigationMenuLinks, each a large name that may hold a <small> line. */
function NavigationMenuContent({ className, children, onPointerOver, onFocus, onPointerLeave, ...props }: React.ComponentProps<typeof NavigationMenuPrimitive.Content>) {
  const variant = React.useContext(VariantContext)
  // lead: which name stands as the headline. The first, until another is pointed at or focused.
  const [lead, setLead] = React.useState(0)
  const links = React.Children.toArray(children).filter(React.isValidElement<{ children?: React.ReactNode }>)
  const pick = (from: EventTarget) => {
    const a = from instanceof Element ? from.closest("[data-slot=navigation-menu-link]") : null
    const all = a?.parentElement ? [...a.parentElement.children] : []
    if (a && all.includes(a)) setLead(all.indexOf(a))
  }
  return (
    <NavigationMenuPrimitive.Content
      data-slot="navigation-menu-content"
      className={cn("db-navmenu-panel", className)}
      onPointerOver={(e) => (onPointerOver?.(e), variant === "lead" && pick(e.target))}
      onFocus={(e) => (onFocus?.(e), variant === "lead" && pick(e.target))}
      onPointerLeave={(e) => (onPointerLeave?.(e), variant === "inline" && held(e))}
      {...props}
    >
      {variant === "lead" ? (
        <>
          <div data-slot="navigation-menu-names" className="db-navmenu-names">
            {links.map((link, i) => React.cloneElement(link as React.ReactElement<{ "data-lead"?: boolean }>, { "data-lead": i === lead || undefined }))}
          </div>
          {links[lead] ? (
            <div key={lead} data-slot="navigation-menu-lead" aria-hidden="true" className="db-navmenu-lead">
              {links[lead].props.children}
            </div>
          ) : null}
        </>
      ) : (
        children
      )}
    </NavigationMenuPrimitive.Content>
  )
}

function NavigationMenuLink({ className, ...props }: React.ComponentProps<typeof NavigationMenuPrimitive.Link>) {
  return <NavigationMenuPrimitive.Link data-slot="navigation-menu-link" className={className} {...props} />
}

export { type NavigationMenuProps, NavigationMenu, NavigationMenuList, NavigationMenuItem, NavigationMenuTrigger, NavigationMenuContent, NavigationMenuLink }

@layer components {
  /* ── db-navmenu ── small words open a panel of large names.
     Radix marks each trigger and panel with data-state. The panel hangs under the
     whole list: Radix wraps the list in a positioned box, so the items stay static. */
  .db-navmenu { position: relative; }
  .db-navmenu [data-slot="navigation-menu-list"] { list-style: none; margin: 0; padding: 0 0 var(--db-space-3); display: flex; flex-wrap: wrap; column-gap: var(--db-space-6); }
  .db-navmenu [data-slot="navigation-menu-item"] { position: static; }
  .db-navmenu :is([data-slot="navigation-menu-trigger"], [data-slot="navigation-menu-item"] > [data-slot="navigation-menu-link"]) {
    appearance: none; border: 0; background: none; margin: 0; padding: 0; font: inherit; color: var(--db-graphite); text-decoration: none; cursor: pointer;
    transition: color var(--db-allegro);
  }
  .db-navmenu :is([data-slot="navigation-menu-trigger"], [data-slot="navigation-menu-item"] > [data-slot="navigation-menu-link"]):is(:hover, [data-state="open"], [data-force~="hover"]) { color: var(--db-ink); }
  .db-navmenu [data-slot="navigation-menu-trigger"]::after {
    content: "↓" / ""; display: inline-block; margin-inline-start: 0.3em; font-size: 0.72em; color: var(--db-pencil);
    transition: rotate var(--db-moderato) var(--db-spiccato);
  }
  .db-navmenu [data-slot="navigation-menu-trigger"][data-state="open"]::after { rotate: 180deg; }
  .db-navmenu-panel {
    position: absolute; z-index: 20; inset-inline: 0; inset-block-start: 100%; padding: var(--db-space-6) 0 var(--db-space-7);
    background: var(--db-paper);
    display: grid; grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr)); gap: var(--db-space-4) var(--db-gutter); align-content: start;
    animation: db-navmenu-in var(--db-moderato) var(--db-exhale);
  }
  .db-navmenu-panel[data-state="closed"] { animation: db-navmenu-out var(--db-allegro) var(--db-breath) forwards; }
  .db-navmenu-panel::before { content: ""; position: absolute; inset: 0 0 auto; height: var(--db-hairline); background: var(--db-ink); transform-origin: 0 50%; }
  :is([dir="rtl"], [dir="rtl"] *) .db-navmenu-panel::before { transform-origin: 100% 50%; }
  .db-navmenu-panel[data-state="open"]::before { animation: db-draw-x var(--db-andante) var(--db-exhale) backwards; }
  .db-navmenu-panel[data-state="open"] > * { animation: db-arrive var(--db-andante) var(--db-exhale) backwards; animation-delay: calc(sibling-index() * var(--db-arpeggio)); }
  .db-navmenu-panel > a {
    display: grid; font-size: var(--db-mf); line-height: var(--db-mf-lh); letter-spacing: var(--db-mf-tr); font-weight: 200; color: var(--db-ink); text-decoration: none;
    transition: font-weight var(--db-moderato) var(--db-exhale);
  }
  .db-navmenu-panel > a:is(:hover, :focus-visible, [data-force~="hover"]) { font-weight: 500; }
  .db-navmenu-panel small { font-size: var(--db-pp); line-height: var(--db-pp-lh); letter-spacing: var(--db-pp-tr); font-weight: 400; color: var(--db-pencil); }
  /* lead: a contents page. The names stand small in a narrow column; the one pointed at or focused (the first, at
     first) is set beside them as the headline, with its line under it, and steps up each time it changes. */
  .db-navmenu[data-variant="lead"] .db-navmenu-panel { grid-template-columns: minmax(9rem, 15rem) minmax(0, 1fr); }
  .db-navmenu-names { display: grid; justify-items: start; align-content: start; gap: var(--db-space-2); padding-block-start: 0.35em; }
  .db-navmenu-names > a {
    display: grid; font-size: var(--db-mp); line-height: var(--db-mp-lh); letter-spacing: var(--db-mp-tr); color: var(--db-graphite); text-decoration: none;
    transition: color var(--db-allegro);
  }
  .db-navmenu-names > a:is([data-lead], :hover, :focus-visible, [data-force~="hover"]) { color: var(--db-ink); }
  .db-navmenu-names small { display: none; }
  .db-navmenu-lead {
    display: grid; align-content: start; font-size: var(--db-ff); line-height: var(--db-ff-lh); letter-spacing: var(--db-ff-tr); font-weight: 200; color: var(--db-ink);
    animation: db-arrive var(--db-moderato) var(--db-exhale);
  }
  .db-navmenu-lead small { max-inline-size: 36ch; margin-block-start: var(--db-space-3); font-size: var(--db-p); line-height: var(--db-p-lh); letter-spacing: 0; color: var(--db-graphite); }
  /* A phone has no pointer to lead with: the names keep their lines, and the headline stands down. */
  @media (max-width: 40rem) {
    .db-navmenu[data-variant="lead"] .db-navmenu-panel { grid-template-columns: minmax(0, 1fr); }
    .db-navmenu-names small { display: block; }
    .db-navmenu-lead { display: none; }
  }

  /* inline: one line of thought, as "Healthy habits → for creatives". Pressing a word opens its names into the line
     after its arrow, larger, on the same baseline; the words after it make room, and the others step back. */
  .db-navmenu[data-variant="inline"] [data-slot="navigation-menu-list"] { align-items: baseline; column-gap: var(--db-space-5); row-gap: var(--db-space-2); padding-block-end: 0; }
  .db-navmenu[data-variant="inline"] [data-slot="navigation-menu-item"] { display: inline-flex; flex-wrap: wrap; align-items: baseline; column-gap: var(--db-space-4); }
  .db-navmenu[data-variant="inline"] [data-slot="navigation-menu-trigger"]::after { content: "→" / ""; rotate: none; transition: color var(--db-allegro), translate var(--db-moderato) var(--db-exhale); }
  .db-navmenu[data-variant="inline"] [data-slot="navigation-menu-trigger"][data-state="open"]::after { color: var(--db-ink); translate: 0.15em 0; }
  :is([dir="rtl"], [dir="rtl"] *) .db-navmenu[data-variant="inline"] [data-slot="navigation-menu-trigger"]::after { scale: -1 1; }
  :is([dir="rtl"], [dir="rtl"] *) .db-navmenu[data-variant="inline"] [data-slot="navigation-menu-trigger"][data-state="open"]::after { translate: -0.15em 0; }
  .db-navmenu[data-variant="inline"]:has(.db-navmenu-panel[data-state="open"]) :is([data-slot="navigation-menu-trigger"], [data-slot="navigation-menu-item"] > [data-slot="navigation-menu-link"]):not([data-state="open"]) { color: var(--db-pencil); }
  .db-navmenu[data-variant="inline"] .db-navmenu-panel {
    position: static; display: inline-flex; align-items: baseline; column-gap: var(--db-space-4); padding: 0; background: none;
    overflow: clip; overflow-clip-margin: 0.3em; white-space: nowrap; animation: db-navmenu-open var(--db-andante) var(--db-exhale);
  }
  .db-navmenu[data-variant="inline"] .db-navmenu-panel[data-state="closed"] { animation: db-navmenu-shut var(--db-moderato) var(--db-breath) forwards; }
  .db-navmenu[data-variant="inline"] .db-navmenu-panel::before { content: none; }
  .db-navmenu[data-variant="inline"] .db-navmenu-panel[data-state="open"] > * { animation: none; }
  .db-navmenu[data-variant="inline"] .db-navmenu-panel > a { display: inline; }
  .db-navmenu[data-variant="inline"] .db-navmenu-panel small { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  @media (max-width: 40rem) {
    .db-navmenu[data-variant="inline"] .db-navmenu-panel { flex-wrap: wrap; white-space: normal; row-gap: 0; }
    .db-navmenu[data-variant="inline"] .db-navmenu-panel > a { font-size: var(--db-mp); line-height: var(--db-mp-lh); font-weight: 300; }
  }
  @keyframes db-navmenu-open { from { inline-size: 0; opacity: 0; } }
  @keyframes db-navmenu-shut { to { inline-size: 0; opacity: 0; } }

  @media (forced-colors: active) {
    .db-navmenu-panel::before { forced-color-adjust: none; background: CanvasText; }
  }
  @keyframes db-navmenu-in { from { opacity: 0; } }
  @keyframes db-navmenu-out { to { opacity: 0; } }
}
